for token,value in {'__CATEGORIES__':len(categories),'__QUESTIONS__':n,'__TOPICS__':topic_count,'__ADDITIONS__':n-72,'__CATEGORY_OPTIONS__':category_options,'__TOPIC_OPTIONS__':topic_options}.items():intro=intro.replace(token,str(value))
refs='''<section class="references" id="references"><div class="eyebrow">KEEP LEARNING</div><h2>Primary references and editorial notes</h2><p>The uploaded bhavs.ai carousel is the source for the 72 labeled question prompts. These links are further reading for checking implementation details; this edition is an original explanatory guide, not a live-verified survey of every product or protocol version.</p><ul><li><a href="https://modelcontextprotocol.io/docs/">Model Context Protocol documentation</a> — primitives, clients, servers, and protocol capabilities.</li><li><a href="https://platform.openai.com/docs/guides/function-calling">OpenAI function calling</a> and <a href="https://platform.openai.com/docs/guides/structured-outputs">structured outputs</a> — tool execution and schema contracts.</li><li><a href="https://www.anthropic.com/engineering/building-effective-agents">Anthropic: Building effective agents</a> — workflow and agent design patterns.</li><li><a href="https://genai.owasp.org/">OWASP GenAI Security Project</a> — application security risks and defenses.</li><li><a href="https://www.nist.gov/itl/ai-risk-management-framework">NIST AI Risk Management Framework</a> — governance and risk management.</li><li><a href="https://arxiv.org/abs/2107.03374">Evaluating Large Language Models Trained on Code</a> — pass@k evaluation context.</li></ul><p>Provider behavior, pricing, model capabilities, SDKs, and MCP revisions change. Verify supported features against the exact version used in your project. “Basic,” “Intermediate,” and “Advanced” describe the expected depth of an answer rather than a universal hiring standard.</p></section><footer>Agentic Atlas Q&A · Edition 02 · Updated 4 November 2026<br>Expandable structure: category → topic → difficulty → question → answer. Keep the accompanying JSON file as the editable content source.</footer></main></div>'''
js='''
const questions=[...document.querySelectorAll('.qa')];const search=document.querySelector('#search'),level=document.querySelector('#level'),origin=document.querySelector('#origin'),categoryFilter=document.querySelector('#category-filter'),topicFilter=document.querySelector('#topic-filter');let lastPractice='';
function visible(){return questions.filter(q=>!q.hidden)}
function filter(){const term=search.value.trim().toLocaleLowerCase();questions.forEach(q=>{const topic=q.closest('.topic'),category=q.closest('.category');const text=q.textContent+' '+topic.querySelector('h3').textContent+' '+category.querySelector('h2').textContent;q.hidden=!((categoryFilter.value==='all'||q.dataset.category===categoryFilter.value)&&(topicFilter.value==='all'||q.dataset.topic===topicFilter.value)&&(!term||text.toLocaleLowerCase().includes(term))&&(level.value==='all'||q.dataset.level===level.value)&&(origin.value==='all'||q.dataset.origin===origin.value));});document.querySelectorAll('.level-group').forEach(g=>g.hidden=![...g.querySelectorAll('.qa')].some(q=>!q.hidden));document.querySelectorAll('.topic').forEach(t=>t.hidden=![...t.querySelectorAll('.qa')].some(q=>!q.hidden));document.querySelectorAll('.category').forEach(c=>c.hidden=![...c.querySelectorAll('.qa')].some(q=>!q.hidden));const n=visible().length;document.querySelector('#count').textContent=n+' of '+questions.length+' questions shown';document.querySelector('#empty').hidden=n>0;document.querySelector('#practice').disabled=n===0;if(!document.querySelector('#study').hidden){document.querySelector('#study').hidden=true;} }
search.addEventListener('input',filter);level.addEventListener('change',filter);origin.addEventListener('change',filter);
categoryFilter.addEventListener('change',()=>{topicFilter.value='all';for(const option of topicFilter.options){option.hidden=option.value!=='all'&&categoryFilter.value!=='all'&&option.dataset.category!==categoryFilter.value;}filter();});topicFilter.addEventListener('change',filter);
function resetScope(){categoryFilter.value='all';topicFilter.value='all';for(const option of topicFilter.options)option.hidden=false;}

document.querySelector('#expand').onclick=()=>visible().forEach(q=>q.open=true);document.querySelector('#collapse').onclick=()=>questions.forEach(q=>q.open=false);document.querySelector('#reset').onclick=()=>{search.value='';level.value='all';origin.value='all';resetScope();filter();};
function practice(){const pool=visible();if(!pool.length)return;const options=pool.length>1?pool.filter(q=>q.id!==lastPractice):pool;const q=options[Math.floor(Math.random()*options.length)];lastPractice=q.id;document.querySelector('#study-question').textContent=q.querySelector('.question').textContent;document.querySelector('#study-meta').textContent=q.closest('.category').querySelector('h2').textContent+' / '+q.dataset.level;document.querySelector('#study-answer').textContent=q.querySelector('.answer p').textContent;document.querySelector('#study-answer').hidden=true;document.querySelector('#reveal').hidden=false;document.querySelector('#study').hidden=false;document.querySelector('#study').scrollIntoView({block:'center',behavior:'smooth'});}
document.querySelector('#practice').onclick=practice;document.querySelector('#next').onclick=practice;document.querySelector('#reveal').onclick=()=>{document.querySelector('#study-answer').hidden=false;document.querySelector('#reveal').hidden=true;};document.querySelector('#close-study').onclick=()=>document.querySelector('#study').hidden=true;
let beforePrint=null;window.addEventListener('beforeprint',()=>{beforePrint=questions.map(q=>q.open);questions.forEach(q=>q.open=true);});window.addEventListener('afterprint',()=>{if(beforePrint)questions.forEach((q,i)=>q.open=beforePrint[i]);beforePrint=null;});document.querySelector('#print').onclick=()=>window.print();
function deepLink(){const id=decodeURIComponent(location.hash.slice(1));const target=document.getElementById(id);if(target&&target.classList.contains('qa')){search.value='';level.value='all';origin.value='all';resetScope();filter();target.open=true;requestAnimationFrame(()=>target.scrollIntoView({block:'start'}));}}
window.addEventListener('hashchange',deepLink);deepLink();document.querySelector('#mobile-nav').onclick=()=>{const n=document.querySelector('#contents');n.classList.toggle('mobile-open');document.querySelector('#mobile-nav').setAttribute('aria-expanded',String(n.classList.contains('mobile-open')));};
'''
css+=(P/'frontend.css').read_text()
