end=intro.index('<aside class="scope">')
hero=f'''<section class="hero" aria-label="About Agentic Atlas"><div class="hero-copy"><div class="eyebrow">A FIELD GUIDE FOR THE AI BUILDER</div><h1>Agentic Atlas<br><span>Q&amp;A.</span></h1><p class="intro">Explore how AI agents think, act, and work together. From your first concept to the systems you build next.</p><div class="hero-links"><a href="#study-library">Explore the atlas ↗</a><a class="secondary" href="#category-1">Start with the fundamentals</a></div></div><aside class="hero-visual" aria-label="Explore connected agent concepts"><div class="visual-label">A CONNECTED FIELD. A CLEARER VIEW.</div><div class="atlas-orbit"><div class="orbit-ring" aria-hidden="true"></div><div class="orbit-center" aria-hidden="true">A</div><a href="#category-3" class="orbit-node tools">↗ Tools &amp; actions</a><a href="#category-19" class="orbit-node memory">◌ Memory</a><a href="#category-15" class="orbit-node planning">◇ Planning</a><a href="#category-8" class="orbit-node evals">✓ Evaluation</a></div><div class="visual-caption">Understand the parts. See the whole system.</div></aside></section><div class="stats"><div class="stat"><strong>{len(categories)}</strong><span>Knowledge categories</span></div><div class="stat"><strong>{topic_count}</strong><span>Topics to explore</span></div><div class="stat"><strong>{n}</strong><span>Questions. Real answers.</span></div><div class="stat"><strong>3 levels</strong><span>Basic → Intermediate → Advanced</span></div></div>'''
intro=intro[:start]+hero+intro[end:]
