intro=intro.replace('AGENTIC ATLAS Q&A','Agentic Atlas Q&amp;A')
js+='''
const categoryLinks=[...document.querySelectorAll('.sidebar a')];
const observer=new IntersectionObserver(entries=>{for(const entry of entries){if(entry.isIntersecting){categoryLinks.forEach(a=>{const active=a.getAttribute('href')==='#'+entry.target.id;a.classList.toggle('nav-current',active);if(active)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current');});}}},{rootMargin:'-5% 0px -65% 0px',threshold:0});document.querySelectorAll('.category').forEach(c=>observer.observe(c));
categoryLinks.forEach(a=>a.addEventListener('click',()=>{search.value='';level.value='all';origin.value='all';resetScope();filter();if(innerWidth<=760){document.querySelector('#contents').classList.remove('mobile-open');document.querySelector('#mobile-nav').setAttribute('aria-expanded','false');}}));
'''

